class SupplierClaimCandidate {final String returnItemId,returnId,invoiceId,invoiceNumber,businessName,sourceLotId,lotCode,receivingBatchId,farmerId,farmerName,farmName,productName,unit,conditionCode,resolution,existingClaimId,existingClaimStatus;final double returnQuantity,farmerUnitCost,recommendedClaimAmount;const SupplierClaimCandidate({required this.returnItemId,required this.returnId,required this.invoiceId,required this.invoiceNumber,required this.businessName,required this.sourceLotId,required this.lotCode,required this.receivingBatchId,required this.farmerId,required this.farmerName,required this.farmName,required this.productName,required this.unit,required this.returnQuantity,required this.conditionCode,required this.resolution,required this.farmerUnitCost,required this.recommendedClaimAmount,required this.existingClaimId,required this.existingClaimStatus});factory SupplierClaimCandidate.fromSupabase(Map<String,dynamic>d){double n(dynamic v)=>v is num?v.toDouble():double.tryParse(v?.toString()??'')??0;return SupplierClaimCandidate(returnItemId:(d['return_item_id']??'').toString(),returnId:(d['return_id']??'').toString(),invoiceId:(d['invoice_id']??'').toString(),invoiceNumber:(d['invoice_number']??'').toString(),businessName:(d['business_name']??'Wholesale business').toString(),sourceLotId:(d['source_lot_id']??'').toString(),lotCode:(d['lot_code']??'').toString(),receivingBatchId:(d['receiving_batch_id']??'').toString(),farmerId:(d['farmer_id']??'').toString(),farmerName:(d['farmer_name']??'').toString(),farmName:(d['farm_name']??'').toString(),productName:(d['product_name']??'Produce').toString(),unit:(d['unit']??'unit').toString(),returnQuantity:n(d['return_quantity']),conditionCode:(d['condition_code']??'unknown').toString(),resolution:(d['resolution']??'pending').toString(),farmerUnitCost:n(d['farmer_unit_cost']),recommendedClaimAmount:n(d['recommended_claim_amount']),existingClaimId:(d['existing_claim_id']??'').toString(),existingClaimStatus:(d['existing_claim_status']??'').toString());}}
class SupplierReturnClaimRow {final String id,claimNumber,returnItemId,returnId,invoiceId,invoiceNumber,businessName,farmerId,farmerName,farmName,productName,unit,status,reason,recoveryReference;final double returnQuantity,claimedAmount,approvedAmount,recoveredAmount;final DateTime? createdAt;const SupplierReturnClaimRow({required this.id,required this.claimNumber,required this.returnItemId,required this.returnId,required this.invoiceId,required this.invoiceNumber,required this.businessName,required this.farmerId,required this.farmerName,required this.farmName,required this.productName,required this.unit,required this.returnQuantity,required this.claimedAmount,required this.approvedAmount,required this.recoveredAmount,required this.status,required this.reason,required this.recoveryReference,required this.createdAt});factory SupplierReturnClaimRow.fromSupabase(Map<String,dynamic>d){double n(dynamic v)=>v is num?v.toDouble():double.tryParse(v?.toString()??'')??0;return SupplierReturnClaimRow(id:(d['claim_id']??'').toString(),claimNumber:(d['claim_number']??'').toString(),returnItemId:(d['return_item_id']??'').toString(),returnId:(d['return_id']??'').toString(),invoiceId:(d['invoice_id']??'').toString(),invoiceNumber:(d['invoice_number']??'').toString(),businessName:(d['business_name']??'Wholesale business').toString(),farmerId:(d['farmer_id']??'').toString(),farmerName:(d['farmer_name']??'').toString(),farmName:(d['farm_name']??'').toString(),productName:(d['product_name']??'Produce').toString(),unit:(d['unit']??'unit').toString(),returnQuantity:n(d['return_quantity']),claimedAmount:n(d['claimed_amount']),approvedAmount:n(d['approved_amount']),recoveredAmount:n(d['recovered_amount']),status:(d['status']??'submitted').toString(),reason:(d['reason']??'').toString(),recoveryReference:(d['recovery_reference']??'').toString(),createdAt:DateTime.tryParse((d['created_at']??'').toString()));}}
class ReturnFinanceReconciliationSummary {final double credits,refunds,openClaims,approvedClaims,recoveredClaims;const ReturnFinanceReconciliationSummary({required this.credits,required this.refunds,required this.openClaims,required this.approvedClaims,required this.recoveredClaims});factory ReturnFinanceReconciliationSummary.fromSupabase(Map<String,dynamic>d){double n(dynamic v)=>v is num?v.toDouble():double.tryParse(v?.toString()??'')??0;return ReturnFinanceReconciliationSummary(credits:n(d['finalized_customer_credits']),refunds:n(d['paid_customer_refunds']),openClaims:n(d['open_supplier_claims']),approvedClaims:n(d['approved_supplier_claims']),recoveredClaims:n(d['recovered_supplier_claims']));}}
Future<List<SupplierClaimCandidate>> fetchSupplierClaimCandidates()async{await requireAdminAccess();final r=await supabase.rpc('admin_list_supplier_claim_candidates');return(r as List).map((x)=>SupplierClaimCandidate.fromSupabase(Map<String,dynamic>.from(x as Map))).toList();}
Future<List<SupplierReturnClaimRow>> fetchSupplierReturnClaims({String status='open'})async{await requireAdminAccess();final r=await supabase.rpc('admin_list_supplier_return_claims',params:{'p_status':status,'p_limit':200});return(r as List).map((x)=>SupplierReturnClaimRow.fromSupabase(Map<String,dynamic>.from(x as Map))).toList();}
Future<ReturnFinanceReconciliationSummary> fetchReturnFinanceReconciliationSummary()async{await requireAdminAccess();final r=await supabase.rpc('admin_return_finance_reconciliation_summary');if(r is List&&r.isNotEmpty)return ReturnFinanceReconciliationSummary.fromSupabase(Map<String,dynamic>.from(r.first as Map));if(r is Map)return ReturnFinanceReconciliationSummary.fromSupabase(Map<String,dynamic>.from(r));throw Exception('Reconciliation summary could not be loaded.');}
Future<void> createSupplierClaim(SupplierClaimCandidate c,double amount,String reason)async{await requireAdminAccess();await supabase.rpc('admin_create_supplier_return_claim',params:{'p_return_item_id':c.returnItemId,'p_claim_amount':amount,'p_reason':reason.trim(),'p_notes':''});}
Future<void> approveSupplierClaim(SupplierReturnClaimRow c,double amount)async{await requireAdminAccess();await supabase.rpc('admin_approve_supplier_return_claim',params:{'p_claim_id':c.id,'p_approved_amount':amount,'p_notes':''});}
Future<void> recoverSupplierClaim(SupplierReturnClaimRow c,double amount,String reference)async{await requireAdminAccess();await supabase.rpc('admin_record_supplier_claim_recovery',params:{'p_claim_id':c.id,'p_amount':amount,'p_reference':reference.trim(),'p_notes':''});}
Future<void> closeSupplierClaim(SupplierReturnClaimRow c,String status,String reason)async{await requireAdminAccess();await supabase.rpc('admin_close_supplier_return_claim',params:{'p_claim_id':c.id,'p_status':status,'p_reason':reason.trim()});}

class SupplierClaimsScreen extends StatefulWidget{const SupplierClaimsScreen({super.key});@override State<SupplierClaimsScreen>createState()=>_SupplierClaimsScreenState();}
class _SupplierClaimsScreenState extends State<SupplierClaimsScreen>{late Future<List<dynamic>>_future;String _status='open';@override void initState(){super.initState();_future=_load();}Future<List<dynamic>>_load()=>Future.wait<dynamic>([fetchSupplierClaimCandidates(),fetchSupplierReturnClaims(status:_status),fetchReturnFinanceReconciliationSummary()]);Future<void>_refresh()async{final n=_load();setState(()=>_future=n);await n;}Color _color(String s){if(s=='recovered')return FarmColors.success;if(s=='rejected'||s=='waived')return FarmColors.mutedText;if(s=='approved')return FarmColors.warning;return FarmColors.danger;}
Future<void>_create(SupplierClaimCandidate c)async{final a=TextEditingController(text:c.recommendedClaimAmount.toStringAsFixed(2));final reason=TextEditingController(text:'Returned ${c.conditionCode} produce');final ok=await showDialog<bool>(context:context,builder:(dc)=>AlertDialog(title:Text('Claim • ${c.farmName.isNotEmpty?c.farmName:c.farmerName}'),content:Column(mainAxisSize:MainAxisSize.min,children:[Text('${c.productName} • ${c.returnQuantity.toStringAsFixed(1)} ${c.unit} • Lot ${c.lotCode}',style:const TextStyle(fontWeight:FontWeight.w800)),const SizedBox(height:10),TextField(controller:a,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Claim amount')),const SizedBox(height:8),TextField(controller:reason,decoration:const InputDecoration(labelText:'Reason'))]),actions:[TextButton(onPressed:()=>Navigator.of(dc).pop(false),child:const Text('Cancel')),ElevatedButton(onPressed:()=>Navigator.of(dc).pop(true),child:const Text('Submit Claim'))]));if(ok==true){final v=double.tryParse(a.text.trim().replaceAll(',',''))??0;if(v>0){try{await createSupplierClaim(c,v,reason.text);await _refresh();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(friendlyAppError(e))));}}}a.dispose();reason.dispose();}
Future<void>_approve(SupplierReturnClaimRow c)async{final a=TextEditingController(text:c.claimedAmount.toStringAsFixed(2));final ok=await showDialog<bool>(context:context,builder:(dc)=>AlertDialog(title:Text('Approve ${c.claimNumber}'),content:TextField(controller:a,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Approved amount')),actions:[TextButton(onPressed:()=>Navigator.of(dc).pop(false),child:const Text('Cancel')),ElevatedButton(onPressed:()=>Navigator.of(dc).pop(true),child:const Text('Approve'))]));if(ok==true){final v=double.tryParse(a.text.trim().replaceAll(',',''))??0;try{await approveSupplierClaim(c,v);await _refresh();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(friendlyAppError(e))));}}a.dispose();}
Future<void>_recover(SupplierReturnClaimRow c)async{final remaining=c.approvedAmount-c.recoveredAmount;final a=TextEditingController(text:remaining.toStringAsFixed(2));final ref=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(dc)=>AlertDialog(title:Text('Record recovery • ${c.claimNumber}'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:a,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Recovered / deducted amount')),const SizedBox(height:8),TextField(controller:ref,decoration:const InputDecoration(labelText:'Reference'))]),actions:[TextButton(onPressed:()=>Navigator.of(dc).pop(false),child:const Text('Cancel')),ElevatedButton(onPressed:()=>Navigator.of(dc).pop(true),child:const Text('Record'))]));if(ok==true){final v=double.tryParse(a.text.trim().replaceAll(',',''))??0;if(v>0&&ref.text.trim().isNotEmpty){try{await recoverSupplierClaim(c,v,ref.text);await _refresh();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(friendlyAppError(e))));}}}a.dispose();ref.dispose();}
@override Widget build(BuildContext context)=>Scaffold(backgroundColor:FarmColors.background,appBar:AppBar(title:const Text('Supplier Claims')),body:FutureBuilder<List<dynamic>>(future:_future,builder:(context,s){if(s.connectionState==ConnectionState.waiting&&s.data==null)return const Center(child:CircularProgressIndicator());if(s.hasError&&s.data==null)return Center(child:Text(friendlyAppError(s.error!)));final d=s.data??const<dynamic>[];final candidates=d.isNotEmpty?d[0]as List<SupplierClaimCandidate>:<SupplierClaimCandidate>[];final claims=d.length>1?d[1]as List<SupplierReturnClaimRow>:<SupplierReturnClaimRow>[];final summary=d.length>2?d[2]as ReturnFinanceReconciliationSummary:const ReturnFinanceReconciliationSummary(credits:0,refunds:0,openClaims:0,approvedClaims:0,recoveredClaims:0);return RefreshIndicator(onRefresh:_refresh,child:ListView(physics:const AlwaysScrollableScrollPhysics(),padding:const EdgeInsets.fromLTRB(16,16,16,110),children:[
FarmCard(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Returns financial reconciliation',style:TextStyle(fontSize:17,fontWeight:FontWeight.w900)),const SizedBox(height:7),Wrap(spacing:12,runSpacing:6,children:[Text('Credits ${formatJmd(summary.credits)}',style:const TextStyle(fontWeight:FontWeight.w800)),Text('Refunds ${formatJmd(summary.refunds)}',style:const TextStyle(fontWeight:FontWeight.w800)),Text('Recovered ${formatJmd(summary.recoveredClaims)}',style:const TextStyle(color:FarmColors.success,fontWeight:FontWeight.w900))])])),const SizedBox(height:14),const Text('Claim Candidates',style:TextStyle(fontSize:16,fontWeight:FontWeight.w900)),const SizedBox(height:8),if(candidates.where((c)=>c.existingClaimId.isEmpty).isEmpty)const FarmCard(child:Text('No new traceable supplier-claim candidates.'))else ...candidates.where((c)=>c.existingClaimId.isEmpty).take(20).map((c)=>Padding(padding:const EdgeInsets.only(bottom:8),child:FarmCard(padding:const EdgeInsets.all(12),child:Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${c.productName} • ${c.farmName.isNotEmpty?c.farmName:c.farmerName}',style:const TextStyle(fontWeight:FontWeight.w900)),Text('${c.conditionCode} • Lot ${c.lotCode} • Recommended ${formatJmd(c.recommendedClaimAmount)}',style:const TextStyle(color:FarmColors.mutedText,fontSize:9.8,fontWeight:FontWeight.w700))])),OutlinedButton(onPressed:()=>_create(c),child:const Text('Claim'))])))),const SizedBox(height:16),SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:['open','submitted','approved','recovered','waived','rejected','all'].map((v)=>Padding(padding:const EdgeInsets.only(right:7),child:ChoiceChip(label:Text(v[0].toUpperCase()+v.substring(1)),selected:_status==v,onSelected:(_){setState((){_status=v;_future=_load();});}))).toList())),const SizedBox(height:10),if(claims.isEmpty)const FarmEmptyState(icon:Icons.agriculture_